using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Estimation.DataProcessing;

internal sealed class NativeDeclaredProbabilityPolytopeDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The native feasible class is generated by finitely many actual probability laws "
            + "on its original finite carrier, with exact label, source and support constraints.",
        H("Finite Convex Hulls of Native Declared Probability Laws"),
        Blocks(Describe.Lean(
            DescribeId.Create("native-declared-probability-polytope"),
            DeclarationHandle.Create(
                "D5/S3/Estimation/DataProcessing/NativeDeclaredProbabilityPolytope.exists_native_finite_hull"),
            H("Actual probability laws generate the entire feasible class"),
            StatementSource.FromAuthor(FormulaDsl.Disp(FormulaDsl.Seq(
                FormulaDsl.Exists, Id("V"), FormulaDsl.InMacro,
                Call("Finset", Call("ProbabilityMeasure", Id("W"))), FormulaDsl.Comma,
                Equal(Call("convexHull", Call("massVectorImage", Id("V"))),
                    Call("massVectorImage", Id("F")))))),
            AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text(
                    "This authored display abbreviates the coordinate convex-hull equality "
                        + "within the full native theorem. It is not a generated theorem type "
                        + "or a checked equivalence with that type.")),
                Paragraph(Text(
                    "W, Z and U are finite measurable types with measurable singletons. "
                        + "label maps W to Z and source maps W to U. A is any subset of W. "
                        + "Q is an actual probability measure on Z and rho is an actual "
                        + "probability measure on W. No nonempty-feasible-class premise, strict "
                        + "positivity premise or rational-mass premise is imposed.")),
                Paragraph(Text(
                    "F consists exactly of those native probability measures theta whose "
                        + "label pushforward is Q, whose full source pushforward equals the "
                        + "source pushforward of this same rho, and whose mass on A is one. "
                        + "The source target is not a separately chosen probability law, and "
                        + "the full source equation is not replaced by marginal equations.")),
                Paragraph(Text(
                    "massVector records the real mass of every singleton of W. Its inverse "
                        + "constructs PMF.ofFintype from ENNReal.ofReal of each nonnegative "
                        + "coordinate, then takes the actual induced probability measure. "
                        + "The two maps are inverses. Zero coordinates remain on W; no support "
                        + "subtype or smaller carrier is used.")),
                Paragraph(Text(
                    "For every finite indexed family of native laws and nonnegative real "
                        + "coefficients, equality to their ENNReal-weighted measure sum is "
                        + "equivalent to equality to the corresponding real coordinate sum. "
                        + "When the coefficients sum to one, this is the exact finite convex "
                        + "affine correspondence, in both directions.")),
                Paragraph(Text(
                    "Under this correspondence, deterministic pushforwards become sums over "
                        + "their full fibers, and mass one on A is equivalent to zero mass at "
                        + "every original symbol outside A. The image of F is exactly the "
                        + "standard simplex sliced by the label, source and outside-support "
                        + "linear equations; both directions of this image equality are supplied.")),
                Paragraph(Text(
                    "The finite-simplex source argument supplies a finite set of coordinate "
                        + "generators. The inverse correspondence reconstructs an actual "
                        + "probability law from each generator. The resulting finite set V "
                        + "lies in F, its mass-coordinate convex hull is exactly the image of F, "
                        + "and a native law belongs to F if and only if it is a nonnegative "
                        + "normalized finite measure sum over that same V.")),
                Paragraph(Text(
                    "An empty feasible class is allowed and has an empty generator set. "
                        + "For the inverse-limit application, rho at level l is the actual "
                        + "projection of the one completed source law. This theorem adds no "
                        + "topological homeomorphism assertion; its conclusion concerns finite "
                        + "probability laws and their affine coordinate representation."))),
            DescribeRole.Theorem))));
}
